SELECT "t8"."order_number", "t8"."line_no", "t8"."item", "t8"."unit_price", "t8"."list_price", 'hold_sales' AS "route", 'price_differences' AS "context"
FROM (SELECT "order_number", "line_no", "item", "unit_price", "price" AS "list_price"
        FROM (SELECT "t1"."order_number", "t1"."line_no", "t1"."item", "t1"."unit_price", "t1"."customer", "t1"."channel", "t1"."placed_date", "t5"."price"
                FROM (SELECT "t0"."order_number", "sales_line"."line_no", "sales_line"."item", "sales_line"."unit_price", "t0"."customer", "t0"."channel", "t0"."placed_date"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    INNER JOIN (SELECT "t4"."order_number", "t4"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                        FROM (SELECT "t3"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t3"."customer", "t3"."channel", "t3"."placed_date"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t3"
                                    INNER JOIN "sales_line" AS "sales_line0" ON "t3"."order_number" = "sales_line0"."order_number") AS "t4"
                            LEFT JOIN "customer_price" ON "t4"."item" = "customer_price"."item" AND "t4"."customer" = "customer_price"."customer" AND "t4"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t4"."placed_date" <= "customer_price"."valid_to")
                            LEFT JOIN "price_list" ON "t4"."item" = "price_list"."item" AND "t4"."channel" = "price_list"."channel" AND "t4"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t4"."placed_date" <= "price_list"."valid_to")) AS "t5" ON "t1"."order_number" = "t5"."order_number" AND "t1"."line_no" = "t5"."line_no") AS "t6"
        WHERE "t6"."price" IS NULL OR ABS("t6"."unit_price" - "t6"."price") > :tolerance) AS "t8"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t34"."order_number", "t34"."customer", "t34"."channel", "t34"."fulfilling_warehouse", "t34"."value", "t34"."placed_date", "t34"."state", COALESCE("t34"."n_short", 0) AS "n_short", COALESCE("t34"."n_price", 0) AS "n_price", COALESCE("t40"."n_due", 0) AS "n_due"
                FROM (SELECT "t22"."order_number", "t22"."customer", "t22"."channel", "t22"."fulfilling_warehouse", "t22"."value", "t22"."placed_date", "t22"."state", "t22"."n_short", "t33"."n_price"
                        FROM (SELECT "t10"."order_number", "t10"."customer", "t10"."channel", "t10"."fulfilling_warehouse", "t10"."value", "t10"."placed_date", "t10"."state", "t21"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t10"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t16"."order_number", "t16"."customer", "t16"."channel", "t16"."fulfilling_warehouse", "t16"."value", "t16"."placed_date", "t16"."state", "t16"."line_no", "t16"."item", "t16"."quantity", "t16"."unit_price", "t16"."ext_sales_price", "t16"."warehouse", "t16"."sold_date", "t16"."customer0", "t16"."channel0", "t16"."as_of_date", "t16"."quantity_on_hand", "t17"."warehouse" AS "warehouse0", "t17"."from_date", "t17"."to_date", "t17"."reason", COALESCE("t16"."quantity_on_hand", 0) AS "on_hand", "t17"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."ext_sales_price", "t13"."warehouse", "t13"."sold_date", "t13"."customer0", "t13"."channel0", "t15"."as_of_date", "t15"."quantity_on_hand"
                                                        FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t12"
                                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t12"."order_number" = "sales_line1"."order_number") AS "t13"
                                                            LEFT JOIN (SELECT "inventory"."as_of_date", "inventory"."item", "inventory"."warehouse", "inventory"."quantity_on_hand"
                                                                FROM "inventory"
                                                                    INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY "item", "warehouse") AS "t14" ON "inventory"."item" = "t14"."item" AND "inventory"."warehouse" = "t14"."warehouse" AND "inventory"."as_of_date" = "t14"."_ttrp_latest_n8") AS "t15" ON "t13"."item" = "t15"."item" AND "t13"."warehouse" = "t15"."warehouse") AS "t16"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t17" ON "t16"."warehouse" = "t17"."warehouse") AS "t18"
                                        WHERE "t18"."outage" OR "t18"."on_hand" < "t18"."quantity"
                                        GROUP BY "order_number") AS "t21" ON "t10"."order_number" = "t21"."order_number") AS "t22"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_price"
                                FROM (SELECT "t25"."order_number", "t25"."line_no", "t25"."item", "t25"."unit_price", "t25"."customer", "t25"."channel", "t25"."placed_date", "t29"."price"
                                        FROM (SELECT "t24"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t24"."customer", "t24"."channel", "t24"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t24"
                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t24"."order_number" = "sales_line2"."order_number") AS "t25"
                                            INNER JOIN (SELECT "t28"."order_number", "t28"."line_no", COALESCE("customer_price0"."price", "price_list0"."price") AS "price"
                                                FROM (SELECT "t27"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t27"."customer", "t27"."channel", "t27"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t27"
                                                            INNER JOIN "sales_line" AS "sales_line3" ON "t27"."order_number" = "sales_line3"."order_number") AS "t28"
                                                    LEFT JOIN "customer_price" AS "customer_price0" ON "t28"."item" = "customer_price0"."item" AND "t28"."customer" = "customer_price0"."customer" AND "t28"."placed_date" >= "customer_price0"."valid_from" AND ("customer_price0"."valid_to" IS NULL OR "t28"."placed_date" <= "customer_price0"."valid_to")
                                                    LEFT JOIN "price_list" AS "price_list0" ON "t28"."item" = "price_list0"."item" AND "t28"."channel" = "price_list0"."channel" AND "t28"."placed_date" >= "price_list0"."valid_from" AND ("price_list0"."valid_to" IS NULL OR "t28"."placed_date" <= "price_list0"."valid_to")) AS "t29" ON "t25"."order_number" = "t29"."order_number" AND "t25"."line_no" = "t29"."line_no") AS "t30"
                                WHERE "t30"."price" IS NULL OR ABS("t30"."unit_price" - "t30"."price") > :tolerance
                                GROUP BY "order_number") AS "t33" ON "t22"."order_number" = "t33"."order_number") AS "t34"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t36"."order_number", "t36"."customer", "t36"."channel", "t36"."fulfilling_warehouse", "t36"."value", "t36"."placed_date", "t36"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t36"
                                    INNER JOIN "invoice" ON "t36"."customer" = "invoice"."customer") AS "t37"
                        WHERE "t37"."status" = 'open' AND "t37"."due" < :as_of
                        GROUP BY "order_number") AS "t40" ON "t34"."order_number" = "t40"."order_number") AS "t41"
        WHERE "t41"."n_short" > 0 OR "t41"."n_price" > 0
        GROUP BY "order_number") AS "t44" ON "t8"."order_number" = "t44"."order_number"
